def comps(g,val):
    seen=set(); out=[]
    for r in range(7):
        for c in range(7):
            if g[r][c]==val and (r,c) not in seen:
                st=[(r,c)]; seen.add((r,c)); comp=[]
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dx,b+dy
                        if 0<=x<7 and 0<=y<7 and g[x][y]==val and (x,y) not in seen:
                            seen.add((x,y)); st.append((x,y))
                out.append(comp)
    return out
